import json, urllib.request, urllib.error

def get(url):
    try:
        with urllib.request.urlopen(url, timeout=10) as r:
            body = r.read()
            headers = dict(r.headers)
            return r.status, headers, body
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()
    except Exception as e:
        return None, {}, f"ERR {e!r}".encode()

for base, name in [("http://127.0.0.1:8091","OLD"), ("http://127.0.0.1:8092","NEW")]:
    for path in ["/stats", "/patients"]:
        status, headers, body = get(base+path)
        print(f"\n=== {name} {path} status={status} len={len(body)} ===")
        print("headers:", {k:v for k,v in headers.items() if k.lower() in ("content-type","x-total-count","link","x-next-cursor","x-pagination","x-total")})
        try:
            data = json.loads(body)
            if isinstance(data, dict):
                print("keys:", list(data.keys()))
                for k,v in data.items():
                    if isinstance(v, list):
                        print(f"  {k}: list len={len(v)} first_ids={[x.get('id') if isinstance(x,dict) else str(x)[:40] for x in v[:3]]} last_ids={[x.get('id') if isinstance(x,dict) else str(x)[:40] for x in v[-3:]] if v else []}")
                    else:
                        print(f"  {k}: {repr(v)[:500]}")
            elif isinstance(data, list):
                print(f"list len={len(data)} first={data[:1]}")
            else:
                print(repr(data)[:1000])
        except Exception as e:
            print("non-json body head:", body[:1000])
